/*
 * A307824  Heinz numbers of integer partitions whose augmented differences
 *          are all equal.
 * https://oeis.org/A307824
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn
 * Formula:   a(n) is the nth term of the sorted list of Heinz numbers of
 *            integer partitions whose augmented differences are all equal.
 *            The values are generated by merging the infinite increasing
 *            sequences for each starting prime index c
 * Range:     u8 n <= 21, u16 n <= 60, u32 n <= 60, u64 n <= 60, u128 n <= 60,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>

/* --- Prime generation utilities ---------------------------------------------- */

#define PRIME_SIEVE_LIMIT 3000000U   /* initial sieve limit (covers ~216k primes) */

static uint32_t *prime_list = NULL;    /* array of primes in ascending order */
static size_t    prime_count = 0;      /* number of primes stored */
static size_t    sieve_limit = 0;      /* current sieve limit */

/* Extend the prime sieve to a new numeric limit.  All older primes are discarded. */
static void extend_sieve_to_limit(size_t limit)
{
    bool *is_prime = (bool *)malloc(limit + 1);
    for (size_t i = 0; i <= limit; ++i) is_prime[i] = true;
    is_prime[0] = is_prime[1] = false;

    for (size_t p = 2; p * p <= limit; ++p)
        if (is_prime[p])
            for (size_t j = p * p; j <= limit; j += p)
                is_prime[j] = false;

    size_t new_count = 0;
    for (size_t i = 2; i <= limit; ++i)
        if (is_prime[i]) ++new_count;

    uint32_t *new_list = (uint32_t *)malloc(new_count * sizeof(uint32_t));
    size_t idx = 0;
    for (size_t i = 2; i <= limit; ++i)
        if (is_prime[i]) new_list[idx++] = (uint32_t)i;

    free(is_prime);
    free(prime_list);

    prime_list   = new_list;
    prime_count  = new_count;
    sieve_limit  = limit;
}

/* Ensure that the prime list contains at least 'idx' entries. */
static seq_t get_prime_by_index(idx_t idx)
{
    if (prime_list == NULL) {
        extend_sieve_to_limit(PRIME_SIEVE_LIMIT);
    }
    while (prime_count < (size_t)idx) {
        size_t next_limit = sieve_limit * 2;
        extend_sieve_to_limit(next_limit);
    }
    return (seq_t)prime_list[(size_t)idx - 1];
}

/* --- Heap utilities for merging sequences ------------------------------ */

typedef struct {
    seq_t  value;     /* current Heinz number of this partition */
    idx_t  c;         /* starting prime index of the sequence       */
    idx_t  last_idx;  /* index of the last prime used in this sequence */
} HeapNode;

static HeapNode *heap = NULL;
static size_t   heap_size   = 0;
static size_t   heap_cap    = 0;

static void heap_grow(void)
{
    if (heap_cap == 0) heap_cap = 8;
    else heap_cap <<= 1;
    heap = (HeapNode *)realloc(heap, heap_cap * sizeof(HeapNode));
}

static void heap_push(HeapNode n)
{
    if (heap_size == heap_cap) heap_grow();
    size_t i = heap_size++;
    while (i > 0) {
        size_t p = (i - 1) >> 1;
        if (heap[p].value <= n.value) break;
        heap[i] = heap[p];
        i = p;
    }
    heap[i] = n;
}

static HeapNode heap_pop(void)
{
    HeapNode res = heap[0];
    HeapNode last = heap[--heap_size];
    size_t i = 0;
    while (true) {
        size_t l = (i << 1) + 1;
        if (l >= heap_size) break;
        size_t r = l + 1;
        size_t c = (r < heap_size && heap[r].value < heap[l].value) ? r : l;
        if (last.value <= heap[c].value) break;
        heap[i] = heap[c];
        i = c;
    }
    heap[i] = last;
    return res;
}

/* --- Cache of computed sequence values ----------------------------------- */

static seq_t *cache = NULL;
static size_t cache_len  = 0;
static size_t cache_cap  = 0;
static idx_t  next_c_to_start = 1;  /* next starting prime index to be pushed */

static void cache_grow(size_t min_cap)
{
    if (cache_cap >= min_cap) return;
    if (cache_cap == 0) cache_cap = 8;
    while (cache_cap < min_cap) cache_cap <<= 1;
    cache = (seq_t *)realloc(cache, cache_cap * sizeof(seq_t));
}

/* ------------------------------------------------------------------------ */

seq_t a(idx_t n)
{
    if (n == 0) return (seq_t)0;   /* offset is 1; n=0 is undefined */

    /* Initialise on first call */
    if (cache_len == 0) {
        /* Prime list initialisation */
        get_prime_by_index(1);        /* triggers sieve */

        /* First term a(1) = 1 */
        cache_grow(1);
        cache[0] = (seq_t)1;
        cache_len = 1;

        /* start the sequence for c = 1 (all ones partition) */
        HeapNode first = { get_prime_by_index(1), 1, 1 };
        heap_push(first);
        next_c_to_start = 2;
    }

    /* Generate terms until we have at least n values */
    while (cache_len < (size_t)n) {
        /* Push all new starting sequences whose first prime <= current heap minimum */
        while (heap_size > 0) {
            seq_t p = get_prime_by_index(next_c_to_start);
            if (p > heap[0].value) break;
            HeapNode node = { p, next_c_to_start, next_c_to_start };
            heap_push(node);
            ++next_c_to_start;
        }

        /* Pop next smallest Heinz number */
        HeapNode cur = heap_pop();

        /* Store it in cache */
        cache_grow(cache_len + 1);
        cache[cache_len++] = cur.value;

        /* Compute the next number for the same sequence */
        idx_t next_idx = cur.last_idx + (cur.c - 1);
        seq_t next_prime = get_prime_by_index(next_idx);
        seq_t new_val = cur.value * next_prime;

        HeapNode nxt = { new_val, cur.c, next_idx };
        heap_push(nxt);
    }

    return cache[n - 1];
}
